insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-00000000000f', 'en', null, 'Introduction to Investing', 'A beginner-friendly tour of how investing works — compound growth, asset classes, risk and diversification, low-cost index funds, and building a portfolio. Built from openly-licensed OER Commons material (CC BY). This is education, not financial advice: it explains concepts and evidence-based principles, not recommendations to buy or sell anything.', null, 'daily_life', 15, true, 'business', '{bbbb0003-0000-4000-8000-000000000007}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-00000000000f', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The main point of investing is to…","options":["guarantee you never lose money","put money to work so it can grow over the long term","get rich quickly this month","avoid ever paying any fees"],"answer":1,"explanation":"Investing aims for long-term growth by accepting some risk — it is not a guarantee or a shortcut."},{"prompt":"Compound growth means you earn returns on…","options":["only your original deposit","both your original money and the returns it already earned","only the fees you pay","nothing until you sell"],"answer":1,"explanation":"Returns start earning their own returns — that is compounding."},{"prompt":"Historically, which asset class has had the highest long-run returns AND the biggest swings?","options":["cash","government bonds","stocks","savings accounts"],"answer":2,"explanation":"Stocks have delivered the most growth over long periods but also the most volatility."},{"prompt":"Diversification mainly helps by…","options":["guaranteeing a profit","spreading money across assets so one loss hurts less","removing all risk","increasing fees"],"answer":1,"explanation":"Spreading money reduces the damage from any single holding falling."},{"prompt":"An index fund is a fund that…","options":["a manager uses to pick a few winning stocks","holds the stocks in a whole market index at low cost","only holds cash","guarantees a fixed return"],"answer":1,"explanation":"An index fund tracks an entire market index cheaply, giving instant diversification."},{"prompt":"Using the Rule of 72, money growing at 8% per year roughly doubles in about…","options":["3 years","9 years","20 years","40 years"],"answer":1,"explanation":"72 ÷ 8 = 9 years."},{"prompt":"Which usually charges lower fees?","options":["a low-cost index fund","an actively managed stock-picking fund","they always cost the same","fees do not matter"],"answer":0,"explanation":"Index funds typically have far lower expense ratios than active funds."},{"prompt":"Rebalancing a portfolio means…","options":["selling everything after a drop","returning your mix back to its target allocation","only buying whatever rose most","checking prices every hour"],"answer":1,"explanation":"Rebalancing trims drift and restores your chosen target mix."}]}'::jsonb, null, 10),
  (2, 'Why invest, and the power of compounding', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why people invest and how compound growth turns time into money. Warm-up: from the diagnostic, what does *compounding* add on top of simply saving cash under a mattress?"},{"heading":"The idea","text":"Investing means buying assets you expect to grow, so your money can outpace inflation over time. The engine is *compound growth*: returns start earning returns. Put $1,000 in at 7% a year — after year one you have $1,070; in year two you earn 7% on $1,070, not $1,000, giving $1,144.90. The formula is future value = P × (1 + r)ⁿ, where P is what you invest, r the yearly rate, and n the number of years. Worked example: $1,000 at 7% for 10 years = 1,000 × 1.07¹⁰ ≈ $1,967 — it nearly doubles, and you added nothing extra."},{"heading":"Worked examples with the numbers","text":"The *Rule of 72* is a shortcut: 72 ÷ rate ≈ years to double. At 7%, 72 ÷ 7 ≈ 10.3 years to double. Now add regular investing: $200 a month at 7% for 30 years grows to about $244,000 — yet only $72,000 (200 × 360 months) is money you put in; roughly $172,000 is growth. Start the same plan 10 years later (20 years, not 30) and it reaches only about $104,000. Same monthly amount, same rate — the missing decade of compounding costs far more than it seems."},{"heading":"Your turn","text":"(1) Using the Rule of 72, how long to double at 4%? (2) Roughly how much is $2,000 at 7% for 10 years? (3) If you invest $200/month instead of $100/month, same rate and time, the ending balance roughly does what? (4) True or false: starting 10 years earlier usually matters more than squeezing out a slightly higher return. Answers: (1) 72 ÷ 4 = 18 years; (2) 2,000 × 1.07¹⁰ ≈ $3,935 — about double; (3) it roughly doubles (the result scales with your contribution); (4) true — extra years of compounding are powerful."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating investing like gambling or a guaranteed win — it is neither. Mistake: waiting for the ''perfect'' moment; time in the market usually beats timing the market. Exit: (a) In future value = P × (1 + r)ⁿ, which variable does starting early increase? (b) Rule of 72 at 9%? Answers: n (the number of years); 72 ÷ 9 = 8 years."}]}'::jsonb, 'Compound growth = returns earning their own returns; time is the key ingredient.', 13),
  (3, 'The main asset classes', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main asset classes and say what each one actually is. Warm-up: which asset class historically returns the most and also swings the most?"},{"heading":"The idea","text":"A *stock* is a share of ownership in a company; you profit if it grows in value or pays *dividends*. A *bond* is a loan to a government or company that pays you interest and returns your principal at maturity. *Cash* and cash equivalents (savings accounts, money-market funds) are stable but low-return. *Real estate* is property you own, often for rent or resale. Worked example: a $1,000 bond with a 4% coupon pays $40 of interest each year, and you get your $1,000 back at maturity — predictable, unlike a stock''s uncertain price."},{"heading":"Worked examples with the numbers","text":"Long-run historical US averages (nominal, and never guarantees) are roughly: stocks ~10% a year, bonds ~5%, cash ~2–3%. So $1,000 held for a typical year might grow to about $1,100 in stocks, $1,050 in bonds, and $1,020 in cash. The catch is the range: in a bad year stocks can fall 30–50%, while cash barely moves. Higher average return comes bundled with a wider set of possible outcomes."},{"heading":"Your turn","text":"Classify each: (1) you lend a government money for 10 years at a fixed interest rate; (2) you buy a share of a company; (3) you keep money in a high-yield savings account; (4) you own a rental apartment. Answers: (1) bond, (2) stock, (3) cash, (4) real estate."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming bonds are risk-free — issuers can default, and bond prices fall when interest rates rise. Mistake: thinking cash is fully ''safe'' — it slowly loses purchasing power to inflation. Exit: (a) Which asset class pays a coupon? (b) Which has historically had the highest long-run return and the most volatility? Answers: a bond; stocks."}]}'::jsonb, 'Stock = a slice of ownership; bond = a loan you made that pays interest.', 13),
  (4, 'Risk, return, and diversification', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the risk–return tradeoff and how diversification lowers risk. Warm-up: what kind of risk does diversification mainly cut down?"},{"heading":"The idea","text":"*Risk* is the uncertainty of your returns — how widely outcomes can vary. As a rule, a higher expected return demands accepting bigger ups and downs. *Diversification* spreads your money across many assets so a single loss cannot sink you. Worked example: put all $10,000 into one stock that falls 50% and you are left with $5,000 (−$5,000). Spread the same $10,000 across 10 unrelated holdings of $1,000 each; if one falls 50% (−$500) while the others hold steady, your portfolio is $9,500 — only down 5%."},{"heading":"Worked examples with the numbers","text":"Mixing asset classes smooths the ride. Take a 60/40 portfolio of $10,000: $6,000 in stocks, $4,000 in bonds. In a year when stocks drop 20% and bonds rise 5%, the stocks fall to $4,800 and the bonds grow to $4,200, for a total of $9,000 — a 10% loss, milder than the 20% you''d feel holding only stocks. Assets that don''t move in lockstep (low *correlation*) offset each other, which is the whole point of diversifying."},{"heading":"Your turn","text":"(1) $10,000 in a single stock that drops 40% — what''s it worth? (2) The same $10,000 split evenly across 20 holdings; one falls 40% and the rest stay flat — what''s your loss in percent? (3) Adding bonds to an all-stock portfolio usually raises or lowers volatility? (4) Does diversification remove all risk? Answers: (1) $6,000; (2) that holding is $500 and loses $200, so about −2% (worth $9,800); (3) lowers it; (4) no — market-wide (systematic) risk remains."},{"heading":"Common mistakes & exit ticket","text":"Mistake: owning 10 tech stocks and calling it diversified — they tend to rise and fall together. Mistake: expecting diversification to guarantee gains; it manages risk, it doesn''t promise returns. Exit: (a) Diversification best reduces which risk — company-specific or market-wide? (b) In a 60/40 portfolio, 60% sits in what? Answers: company-specific; stocks."}]}'::jsonb, 'Higher expected return generally comes with higher risk — there is no free lunch.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Compound growth means returns are earned on…","options":["only your original deposit","your principal plus the returns already earned","only your monthly contributions","fees alone"],"answer":1,"explanation":"Compounding is returns earning their own returns."},{"prompt":"By the Rule of 72, money at 6% a year doubles in about…","options":["6 years","12 years","24 years","36 years"],"answer":1,"explanation":"72 ÷ 6 = 12 years."},{"prompt":"A bond is best described as…","options":["a share of ownership in a company","a loan to a company or government that pays interest","a type of savings account","a guarantee of profit"],"answer":1,"explanation":"Bondholders are lenders who receive interest and principal back."},{"prompt":"The highest long-run returns and the biggest swings have historically come from…","options":["cash","bonds","stocks","money-market funds"],"answer":2,"explanation":"Stocks: most growth, most volatility."},{"prompt":"Diversification mainly reduces…","options":["company-specific risk","the need to ever invest","all possible risk","your fees to zero"],"answer":0,"explanation":"Spreading across holdings limits single-company damage, but market-wide risk stays."},{"prompt":"Holding 10 different technology stocks is poorly diversified because they…","options":["are too cheap","tend to move up and down together","pay no dividends","are all bonds"],"answer":1,"explanation":"Similar holdings are highly correlated, so they don''t offset each other."}]}'::jsonb, null, 8),
  (6, 'Index funds and ETFs vs. picking stocks', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compare low-cost index funds and ETFs with stock-picking, and see why costs matter so much. Warm-up: between an index fund and an active fund, which usually charges lower fees?"},{"heading":"The idea","text":"An *index fund* holds every stock in a market index — say a total-market or S&P 500 index — in a single purchase, giving instant diversification. An *ETF* (exchange-traded fund) works similarly but trades like a stock during the day. The evidence is consistent: over long periods, most actively managed funds underperform a low-cost index fund after fees. Worked example: an *expense ratio* of 0.03% on $10,000 costs $3 a year; an active fund at 1.00% costs $100 a year on the same amount."},{"heading":"Worked examples with the numbers","text":"Small fees compound into big gaps. Take $100,000 invested for 30 years. At a 6% net return: 100,000 × 1.06³⁰ ≈ $574,000. At 5% net — just 1% lower because of higher fees: 100,000 × 1.05³⁰ ≈ $432,000. That single extra percentage point of cost quietly drains about $142,000 over 30 years. You can''t control the market''s return, but you can control the fees you pay."},{"heading":"Your turn","text":"(1) Fund A charges 0.05% and Fund B charges 0.80% on $20,000 — what does each cost per year? (2) Does buying one company''s stock give you diversification? (3) Over long horizons, do most active managers beat a low-cost index after fees? (4) How does an ETF mainly differ from an index mutual fund? Answers: (1) A = $10, B = $160; (2) no — that''s single-company risk; (3) no, most underperform; (4) an ETF trades throughout the day like a stock."},{"heading":"Common mistakes & exit ticket","text":"Mistake: chasing last year''s hottest fund or stock, which rarely repeats. Mistake: assuming a higher fee buys a higher return — it usually just lowers your net result. Exit: (a) What is an expense ratio? (b) Which gives instant diversification — one stock, or a total-market index fund? Answers: the annual percentage fee a fund charges; the total-market index fund."}]}'::jsonb, 'Index fund or ETF = buy the whole market cheaply, instead of betting on one company.', 13),
  (7, 'Building and rebalancing a portfolio', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Set a target allocation and rebalance it back over time. Warm-up: what exactly does rebalancing bring a portfolio back to?"},{"heading":"The idea","text":"A *portfolio* is your overall mix of asset classes, chosen for your goal and time horizon. A common starting rule of thumb is to hold roughly (110 − your age)% in stocks and the rest in bonds — so a 30-year-old lands near 80% stocks / 20% bonds. A longer horizon supports more stocks; getting closer to the goal argues for more bonds and cash. Worked example: $10,000 at a 60/40 target = $6,000 in stocks and $4,000 in bonds."},{"heading":"Worked examples with the numbers","text":"Suppose stocks rally so that slice grows to $7,500 while bonds sit at $4,100 — a total of $11,600. Stocks are now 7,500 ÷ 11,600 = 64.7%, above the 60% target. To rebalance, target stocks = 0.60 × 11,600 = $6,960, so you sell $540 of stocks and move it to bonds (now $4,640). Check: 6,960 ÷ 11,600 = 60% and 4,640 ÷ 11,600 = 40%. Rebalancing quietly makes you ''sell high and buy low'' on a schedule, without guessing."},{"heading":"Your turn","text":"(1) $20,000 at a 70/30 target — how many dollars in stocks and in bonds? (2) Using 110 − age, roughly what stock percentage fits a 40-year-old? (3) After a rally your stocks drift to 75% against a 60% target — do you sell or buy stocks to rebalance? (4) You hold $5,000 stocks and $3,000 bonds ($8,000 total) but want 50/50 — what trade fixes it? Answers: (1) $14,000 stocks / $6,000 bonds; (2) about 70%; (3) sell stocks and buy bonds; (4) target $4,000 each, so sell $1,000 of stocks and buy $1,000 of bonds."},{"heading":"Common mistakes & exit ticket","text":"Mistake: never rebalancing, so a long rally silently pushes your risk far above what you intended. Mistake: reacting to scary headlines and abandoning the plan entirely. Exit: (a) Rebalancing returns you to your ___? (b) The 110 − age rule of thumb gives a rough percentage in what? Answers: target allocation; stocks."}]}'::jsonb, 'Rebalancing = trimming what grew back to your target so risk stays where you chose it.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"compound growth","translation":"growth where past returns start earning returns of their own","example":"Compound growth is why starting early matters so much."},{"term":"stock","translation":"a share of ownership in a company","example":"Owning a stock makes you a part-owner entitled to any dividends."},{"term":"bond","translation":"a loan to a government or company that pays interest and returns your principal","example":"A 4% bond on $1,000 pays $40 of interest a year."},{"term":"diversification","translation":"spreading money across many assets so one loss does less damage","example":"Diversification cut the portfolio''s loss to 5% instead of 50%."},{"term":"index fund","translation":"a fund that holds a whole market index at very low cost","example":"One index fund can hold hundreds of companies at once."},{"term":"rebalancing","translation":"trading holdings to return a portfolio to its target allocation","example":"Rebalancing sold some stocks after they rose above the target."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"An index fund is attractive mainly because it offers…","options":["a guaranteed return","low cost and instant diversification","the hottest single stock","no risk at all"],"answer":1,"explanation":"One cheap purchase spreads money across a whole index."},{"prompt":"Over decades, paying 1% more in annual fees tends to…","options":["have no effect","significantly reduce your final wealth","increase your returns","eliminate risk"],"answer":1,"explanation":"Fee drag compounds — about $142,000 lost on $100,000 over 30 years in the example."},{"prompt":"Over long horizons, most actively managed funds…","options":["beat low-cost index funds after fees","underperform low-cost index funds after fees","charge no fees","hold only cash"],"answer":1,"explanation":"The evidence consistently favors low-cost index investing."},{"prompt":"Rebalancing a portfolio means…","options":["selling everything in a downturn","returning your mix to its target allocation","buying only whatever rose the most","checking prices hourly"],"answer":1,"explanation":"It restores the intended asset mix."},{"prompt":"Using 110 − age, a 30-year-old''s rough stock allocation is about…","options":["20%","50%","80%","100%"],"answer":2,"explanation":"110 − 30 = 80% in stocks."},{"prompt":"After a strong rally pushes stocks above your target, rebalancing means you…","options":["buy more stocks","sell some stocks and buy bonds","sell all your bonds","do nothing ever"],"answer":1,"explanation":"You trim the overweight winners back to target — effectively selling high."}]}'::jsonb, null, 8),
  (10, 'Applied project: design a diversified portfolio', 'writing', '{"sections":[{"heading":"The task","text":"Design a simple, diversified portfolio for one personal goal and justify the allocation in your own words. You won''t invest real money — you''ll plan clearly and defend your reasoning. Remember: this is an educational exercise, not financial advice."},{"heading":"Milestones","text":"1) State one goal and its time horizon (e.g. ''retirement in ~30 years'' or ''a home down payment in 4 years''). 2) Choose an asset allocation in percentages (stocks / bonds / cash), using time horizon and the 110 − age rule of thumb as a starting point — a longer horizon supports more stocks. 3) Pick broad, low-cost vehicles (such as a total-market stock index fund and a bond index fund) rather than single companies. 4) Show the dollar split for a sample amount, e.g. $10,000. 5) Explain how and when you''d rebalance back to target."},{"heading":"Self-check rubric","text":"✔ Your percentages add up to 100%. ✔ The stock/bond/cash mix is justified by the time horizon (shorter horizon → more bonds/cash). ✔ It''s genuinely diversified — broad funds, not one company or one sector. ✔ You considered cost (favoring low expense ratios). ✔ You stated a clear rebalancing rule. If all five hold, you''ve built a sound, evidence-based plan. Note once more: this is education, not personalized financial advice."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-00000000000f' and l.position = v.pos
);
